textOptions.schema:
{
  "type": "object",
  "properties": {
    "result": {
      "type": "object",
      "properties": {
        "employee_name": {
          "type": "string"
        },
        "status_category": {
          "type": "string"
        },
        "leave_type": {
          "type": "string"
        },
        "duration_days": {
          "type": "number"
        },
        "decision": {
          "type": "string",
          "enum": ["APPROVED", "REJECTED", "Resubmit", "REFER_TO_HR", "REFER_TO_ALLOCATION"]
        },
        "overridden": {
          "type": "string",
          "enum": ["Yes", "No"],
          "description": "Output 'Yes' if you bypassed standard matched-doer rules for a special case/emergency."
        }
      },
      "required": [
        "employee_name",
        "status_category",
        "leave_type",
        "duration_days",
        "decision"
      ,
        "overridden"],
      "additionalProperties": false
    },
    "reasoning": {
      "type": "string"
    }
  },
  "required": ["result", "reasoning"],
  "additionalProperties": false
}
